import type { ContentCompleteness, Topic, TopicStandard } from '../types';

const edition = 'Supplied PEC Part 1 PDF - edition needs verification';
const reviewed = '2026-09-27';

const completeness = (): ContentCompleteness[] => [
  'Detailed PEC explanation', 'Applicability', 'PEC references', 'Key requirements', 'Formula',
  'Variable definitions', 'Engineering table', 'Engineering figure', 'Worked example #1',
  'Worked example #2', 'Design workflow', 'Decision guide', 'Exceptions', 'Common mistakes',
  'Related topics', 'Source traceability',
].map((item) => ({ item, status: 'complete' }));

function chapter(id: string, title: string, description: string, synonyms: string[], pec: TopicStandard, relatedTopicIds: string[]): Topic {
  return {
    id, title, categoryId: 'conductors', description, synonyms, standards: { pec },
    engineeringExplanation: 'Conductor design is a sequence: establish the required load ampacity, choose the applicable PEC table and temperature column, apply conditions of use, enforce the lowest connected-equipment limit, and then check voltage performance separately.',
    engineeringNotes: ['Keep a calculation record containing the exact table, row, column, ambient, conductor count, factors, terminal rating, route length, and impedance source.'],
    commonMistakes: pec.commonMistakes ?? [], relatedTopicIds, lastReviewed: reviewed,
    reviewStatus: 'Needs verification',
    sourceStatus: 'Source-traced handbook chapter - clauses checked; PEC edition identity still NEEDS VERIFICATION.',
    completeness: completeness(),
  };
}

